using Microsoft.AspNetCore.Http;

namespace Elsa.Http.Options;

/// <summary>
/// Provides various options related to the HTTP activities.
/// </summary>
public class HttpActivityOptions
{
    /// <summary>
    /// The root path at which HTTP activities can be invoked.
    /// </summary>
    public PathString? BasePath { get; set; } = "/workflows";
        
    /// <summary>
    /// The base URL of the server. This should be set to the same value at which the Elsa Server is publicly available. It will be used when generating absolute URLs need to be generated by activities such as SendEmail. 
    /// </summary>
    public Uri BaseUrl { get; set; } = new Uri("https://localhost:5001");

    /// <summary>
    /// The prefix used for API routes.
    /// </summary>
    [Obsolete("Use ApiEndpointOptions from Elsa.Workflows.Api instead.")]
    public string ApiRoutePrefix { get; set; } = "elsa/api";

    /// <summary>
    /// A configurable set of available content types available from the <see cref="WriteHttpResponse"/> activity.
    /// </summary>
    public ISet<string> AvailableContentTypes { get; set; } = new SortedSet<string>
    {
        "application/json", 
        "application/xml", 
        "application/x-www-form-urlencoded", 
        "application/octet-stream",
        "text/plain", 
        "text/html",
        "text/json", 
        "text/xml",
    };

    /// <summary>
    /// A boolean to opt-in if you want to call CompleteAsync() in the HttpResponse Activity
    /// and not waiting for the end of the HttpMiddleware. 
    /// </summary>
    public bool WriteHttpResponseSynchronously { get; set; } = false;

    /// <summary>
    /// The ASP.NET Core rate limiting policy to apply to inbound HTTP workflow trigger routes.
    /// <c>null</c> means unspecified and allows a host to assign a default policy; an empty string disables HTTP workflow trigger rate limiting.
    /// </summary>
    public string? RateLimitingPolicyName { get; set; }

    /// <summary>
    /// First-segment sub-paths under <see cref="BasePath"/> that skip HTTP workflow matching so later
    /// middleware can handle them. Combined Server+Studio hosts use this for Studio's
    /// <c>/workflows/definitions</c> and <c>/workflows/instances</c> routes while keeping legacy
    /// HTTP trigger start/resume under <c>/workflows/{path}</c>. Unmatched HTTP paths still 404.
    /// </summary>
    public IList<string> PassthroughSubPaths { get; set; } = new List<string>();
}
